import React from 'react'
import Button from '@material-ui/core/Button'
import CloudDownloadIcon from '@material-ui/icons/CloudDownload'

const ResumeBtn = () => {
  const basePath = process.env.PUBLIC_URL || ''
  const href = `${basePath}/resume.pdf`

  return (
    <div>
      <Button
        endIcon={<CloudDownloadIcon />}
        variant='text'
        color='primary'
        size='small'
        component='a'
        href={href}
        download='Abdelrahman-Gomaa-Resume.pdf'
        aria-label='Download Abdelrahman Gomaa resume PDF'>
        Download CV
      </Button>
    </div>
  )
}

export default ResumeBtn
