import React from 'react'
import { Typography } from '@material-ui/core'
import { Link } from 'react-router-dom'
import SEO from '../SEO'

const PageNotFound = () => {
  return (
    <div style={{ display: 'flex', justifyContent: 'center', maxWidth: '400', alignItems: 'center' }}>
      <SEO
        title='Page Not Found'
        description='The page you requested was not found on Abdelrahman Gomaa’s portfolio.'
        path='/404'
        noindex
      />
      <Typography color='error' variant='h4' component='h1'>
        Oops! That page can’t be found.
        <Link to='/'>  <Typography variant='h6' color='error' align='center' component='span'>About Me</Typography> </Link>
        <Link to='/resume'>  <Typography variant='h6' color='error' align='center' component='span'>Resume</Typography> </Link>
        <Link to='/projects'>  <Typography variant='h6' color='error' align='center' component='span'>Portfolio</Typography> </Link>
      </Typography>
    </div>
  )
}

export default PageNotFound
