import { Box, CardHeader, Container, Grid, Typography, Zoom } from "@material-ui/core";
import Card from "@material-ui/core/Card";
import CardActionArea from "@material-ui/core/CardActionArea";
import CardActions from "@material-ui/core/CardActions";
import CardContent from "@material-ui/core/CardContent";
import CardMedia from "@material-ui/core/CardMedia";
import IconButton from "@material-ui/core/IconButton";
import { makeStyles } from "@material-ui/core/styles";
import GitHub from "@material-ui/icons/GitHub";
import OpenInNewIcon from "@material-ui/icons/OpenInNew";
import React from "react";
import { personalInfo } from "../../../assets/data/personalInfo"
import SEO from "../../SEO"


const useStyles = makeStyles({
  root: {
    justifyContent: "flex-start",
    flexDirection: "column",
    flexWrap: "nowrap",
  },

  cardRoot: {
    width: 340,
    display: "flex",
    flexDirection: "column",
    margin: "20px",

  },
  cardActionBtn: {
    display: 'flex',
    justifyContent: 'space-between'
  },

  media: {
    height: 250,
    "&:hover": {
      transition: "all 0.5s ease-in-out",
      transform: "scale3d(1.1, 1.1, 0.3)",
    },
  },

  description: {
    whiteSpace: "pre-line",
    flexGrow: 1,
  },

  titleHeader: {
    display: "flex",
    justifyContent: "center",
    fontWeight: 700
  },

  cardContainer: {
    display: "flex",
    justifyContent: "center",
    flexWrap: "wrap",
    alignItems: "flex-start",
  },
});

const Portfolio = () => {
  const classes = useStyles();
  return (
    <>
      <SEO
        title="Projects — Fintech, E-commerce & Full-Stack Work"
        description="Selected projects by Abdelrahman Gomaa: fintech loan platforms, payment gateways, AI agents, food delivery backends, equestrian ticketing, e-commerce, and DevOps CI/CD on AWS."
        path="/projects"
      />
      <Zoom in timeout={{ enter: 500, exit: 500 }}>
        <Container component="article">
          <Grid container className={classes.root}>
            <Typography variant='h4' component='h1' className={classes.titleHeader}>
              Portfolio
            </Typography>
            <Box className={classes.cardContainer}>
              {personalInfo.projects.map((project) => (
                <Card
                  className={classes.cardRoot}
                  elevation={3}
                  key={project.title}
                  component="section"
                >
                  <CardHeader title={project.title} titleTypographyProps={{ component: 'h2', variant: 'h6' }} />

                  <CardActionArea>
                    <CardMedia
                      className={classes.media}
                      image={project.image}
                      title={project.title}
                      alt={project.title}
                    />
                  </CardActionArea>
                  {project.description && (
                    <CardContent>
                      <Typography
                        variant="body2"
                        color="textSecondary"
                        className={classes.description}
                      >
                        {project.description.trim()}
                      </Typography>
                    </CardContent>
                  )}
                  {(project.url || project.githubUrl) && (
                    <CardActions className={classes.cardActionBtn}>
                      {project.url && (
                        <IconButton
                          size="small"
                          color="primary"
                          href={project.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          aria-label={`Open live site: ${project.title}`}
                        >
                          <OpenInNewIcon fontSize="small" />
                        </IconButton>
                      )}
                      {project.githubUrl && (
                        <IconButton
                          size="small"
                          color="primary"
                          href={project.githubUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          aria-label={`View source on GitHub: ${project.title}`}
                        >
                          <GitHub />
                        </IconButton>
                      )}
                    </CardActions>
                  )}
                </Card>
              ))}
            </Box>
          </Grid>
        </Container>
      </Zoom>
    </>
  );
};

export default Portfolio;
