import { Helmet } from 'react-helmet'

const SITE_URL = 'https://abdo20010dx.github.io/portfolio'
const DEFAULT_IMAGE = `${SITE_URL}/og-image.jpg`
const SITE_NAME = 'Abdelrahman Gomaa Portfolio'

/**
 * Per-route document head for title, description, canonical, and social tags.
 * Static defaults also live in public/index.html for the first paint / crawlers.
 */
const SEO = ({
  title,
  description,
  path = '/',
  type = 'website',
  image = DEFAULT_IMAGE,
  noindex = false,
}) => {
  const fullTitle = title.includes('Abdelrahman Gomaa')
    ? title
    : `${title} | Abdelrahman Gomaa`
  const url = `${SITE_URL}${path === '/' ? '/' : path}`

  return (
    <Helmet>
      <html lang='en' />
      <title>{fullTitle}</title>
      <meta name='description' content={description} />
      <link rel='canonical' href={url} />
      {noindex ? (
        <meta name='robots' content='noindex, nofollow' />
      ) : (
        <meta
          name='robots'
          content='index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1'
        />
      )}

      <meta property='og:type' content={type} />
      <meta property='og:url' content={url} />
      <meta property='og:title' content={fullTitle} />
      <meta property='og:description' content={description} />
      <meta property='og:image' content={image} />
      <meta property='og:site_name' content={SITE_NAME} />

      <meta name='twitter:card' content='summary_large_image' />
      <meta name='twitter:title' content={fullTitle} />
      <meta name='twitter:description' content={description} />
      <meta name='twitter:image' content={image} />
    </Helmet>
  )
}

export default SEO
